ALTER TABLE "TEST_AP"."OBPD" WITH PARAMETERS ('CONCAT_ATTRIBUTE'=('$TableName$KeyValue1$KeyValue2$KeyValue3$KeyValue4$KeyValue5$FieldName$','TableName','KeyValue1','KeyValue2','KeyValue3','KeyValue4','KeyValue5','FieldName'));
